"""A tiny evaluator for a small subset of Forth."""

import re


class StackUnderflowError(Exception):
    pass


_NUMBER = re.compile(r"^-?\d+$")


def _is_number(token):
    return bool(_NUMBER.match(token))


class _Deferred:
    """A word in a definition whose meaning is resolved when executed."""

    def __init__(self, forth, name):
        self._forth = forth
        self._name = name

    def __call__(self):
        self._forth._lookup(self._name)()


class Forth:
    def __init__(self):
        self._stack = []
        self._words = {}
        self._builtins = {
            "+": self._add,
            "-": self._sub,
            "*": self._mul,
            "/": self._div,
            "dup": self._dup,
            "drop": self._drop,
            "swap": self._swap,
            "over": self._over,
        }

    # -- stack helpers ---------------------------------------------------

    def _pop(self, count):
        if len(self._stack) < count:
            raise StackUnderflowError("Insufficient number of items in stack")
        values = self._stack[-count:]
        del self._stack[-count:]
        return values

    # -- built-in words ----------------------------------------------------

    def _add(self):
        a, b = self._pop(2)
        self._stack.append(a + b)

    def _sub(self):
        a, b = self._pop(2)
        self._stack.append(b - a)

    def _mul(self):
        a, b = self._pop(2)
        self._stack.append(a * b)

    def _div(self):
        a, b = self._pop(2)
        if b == 0:
            raise ZeroDivisionError("divide by zero")
        quotient = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            quotient = -quotient
        self._stack.append(quotient)

    def _dup(self):
        (a,) = self._pop(1)
        self._stack.append(a)

    def _drop(self):
        self._pop(1)

    def _swap(self):
        a, b = self._pop(2)
        self._stack.extend((b, a))

    def _over(self):
        a, b = self._pop(2)
        self._stack.extend((a, b, a))

    # -- word lookup ---------------------------------------------------------

    def _lookup(self, name):
        action = self._words.get(name)
        if action is None:
            action = self._builtins.get(name)
        if action is None:
            raise ValueError("undefined operation")
        return action

    # -- input processing -----------------------------------------------------

    def process(self, line):
        tokens = line.split()
        if not tokens:
            return
        if tokens[0] == ":":
            self._define(tokens)
        else:
            for token in tokens:
                if _is_number(token):
                    self._stack.append(int(token))
                else:
                    self._lookup(token.lower())()

    def _define(self, tokens):
        if len(tokens) < 2 or _is_number(tokens[1]):
            raise ValueError("illegal operation")
        name = tokens[1].lower()
        body = tokens[2:]
        if ";" in body:
            body = body[: body.index(";")]
        self._words[name] = [self._compile(token) for token in body]

    def _compile(self, token):
        """Compile a token from a definition body into an action.

        Words already known at definition time are bound to their current
        meaning; unknown words are deferred until execution.
        """
        if _is_number(token):
            value = int(token)
            return lambda: self._stack.append(value)
        name = token.lower()
        action = self._words.get(name)
        if action is None:
            action = self._builtins.get(name)
        if action is None:
            return _Deferred(self, name)
        return action

    def result(self):
        return list(self._stack)


def evaluate(input_data):
    forth = Forth()
    for line in input_data:
        forth.process(line)
    return forth.result()

